effect.shader:
// Rotating tiled boxes glow - AM single pass

float sdBox(in vec2 p, in float b){
    vec2 d = abs(p) - vec2(b);
    return length(max(d, 0.0));
}

mat2 rot(float a){ return mat2(cos(a), -sin(a), sin(a), cos(a)); }

void main(){
    vec2 R = acScreenSize;
    vec2 frag = acScreenNorm * R;
    vec2 uv = (frag - 0.5 * R) / max(R.x, 1.0);

    float a = ROT_SPEED * acTime;
    uv = rot(a) * uv;
    uv += 0.5 / SCALE;

    vec2 scaled_uv = SCALE * uv;
    vec2 tile = fract(scaled_uv) - 0.5;
    float square_dist = length(floor(scaled_uv));

    float square_dist_distortion = square_dist * EDGE_FREQ * (1.0 + pow(sin(acTime * EDGE_TIME), 2.0));

    float edge = sin(0.5 * acTime + square_dist_distortion);
    edge *= edge;
    edge = pow(edge, EDGE_POW) * EDGE_GAIN;

    float border = BORDER;
    float value = 1.5 - smoothstep(0.0 - border, 0.0 + border, sdBox(tile, edge));

    value -= square_dist * DIST_COEF;
    value = max(value, 0.0);

    vec3 col = vec3(pow(value, POW_R), pow(value, POW_G), pow(value, POW_B));
    gl_FragColor = vec4(col, 1.0);
}
